            None
        }
    };
    let (Some(skeleton), Some(split)) = (
        parse(skeleton, "the skeleton", &mut r),
        parse(split, "split.json", &mut r),
    ) else {
        return out(None, &r, None);
    };
    let files: Option<Vec<String>> = serde_json::from_str(changed_files).ok().flatten();
    out(
